    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~(0xFUL << GPIO_AFRH_AFSEL8_Pos)) | (8UL << GPIO_AFRH_AFSEL8_Pos);
    GPIOC->AFR[1] = (GPIOC->AFR[1] & ~(0xFUL << GPIO_AFRH_AFSEL9_Pos)) | (8UL << GPIO_AFRH_AFSEL9_Pos);

    /* 4. Configure I2C3 timing while disabled (PE = 0) */
    I2C3->CR1 &= ~I2C_CR1_PE;

