void SystemClock_Config_170MHz(void)
{
    // 1. Enable PWR peripheral clock
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    // 2. Set Voltage Scaling to Range 1 (VOS = 01b)
    PWR->CR1 = (PWR->CR1 & ~PWR_CR1_VOS) | (1U << PWR_CR1_VOS_Pos);
    while (PWR->SR2 & PWR_SR2_VOSF); // Wait until voltage regulator stabilizes

    // 3. Enable Range 1 Boost Mode (clearing R1MODE bit in PWR_CR5 enables boost mode)
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    // 4. Set Flash Latency to 4 Wait States (required for 170 MHz in Boost Mode at 3.6 V)
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS);

    // 5. Ensure HSI16 is ON and stable
    RCC->CR |= RCC_CR_HSION;
    while (!(RCC->CR & RCC_CR_HSIRDY));

    // 6. Configure PLL: Source = HSI16, M = 4, N = 85, R = 2
    //    f_VCO = (16 MHz / 4) * 85 = 340 MHz
    //    f_PLL_R = 340 MHz / 2 = 170 MHz
    RCC->CR &= ~RCC_CR_PLLON;
    while (RCC->CR & RCC_CR_PLLRDY); // Ensure PLL is disabled before configuration

    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSI                      | // HSI16 source
                   ((4U - 1U) << RCC_PLLCFGR_PLLM_Pos)         | // M = 4
                   (85U << RCC_PLLCFGR_PLLN_Pos)               | // N = 85
                   (0U << RCC_PLLCFGR_PLLR_Pos)                | // R = 2 (00b = /2)
                   RCC_PLLCFGR_PLLREN;                           // Enable PLL "R" output

    // 7. Enable PLL and wait for lock
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

