#include "stm32g4xx.h"

void tim1_pa8_pwm_init(void)
{
    /* 1. Enable GPIOA and TIM1 peripheral clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PA8 as Alternate Function AF6 (TIM1_CH1) */
    GPIOA->MODER &= ~GPIO_MODER_MODE8_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos);          /* Alternate Function mode */

    GPIOA->AFR[1] &= ~GPIO_AFRH_AFSEL8_Msk;
    GPIOA->AFR[1] |= (6U << GPIO_AFRH_AFSEL8_Pos);         /* AF6 */

    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);     /* High speed */

    /* 3. Configure TIM1 time-base:
     *    f_TIM1 = 170 MHz
     *    f_PWM  = 170 MHz / ((PSC + 1) * (ARR + 1)) = 170 MHz / (1 * 8500) = 20 kHz
     */
    TIM1->PSC = 0U;
    TIM1->ARR = 8500U - 1U;                                 /* 8499 */

    /* 4. Configure 25% duty cycle:
     *    CCR1 = 8500 * 0.25 = 2125
     */
    TIM1->CCR1 = 2125U;

    /* 5. Configure Channel 1: PWM mode 1 (OC1M = 0110b), enable preload */
    TIM1->CCMR1 &= ~(TIM_CCMR1_CC1S | TIM_CCMR1_OC1M);
    TIM1->CCMR1 |= (0x6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* 6. Enable Channel 1 output, active-high polarity (CC1P = 0) */
    TIM1->CCER &= ~TIM_CCER_CC1P;
    TIM1->CCER |= TIM_CCER_CC1E;

    /* 7. Enable Main Output (MOE) for advanced timer TIM1 */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* 8. Enable auto-reload preload and start counter */
    TIM1->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;
}
```

### Explanation
- **Clock & Pin Routing**: Pin PA8 is mapped to alternate function 6 (AF6) to connect to `TIM1_CH1`. 
- **Time Base**: Since APB2 prescaler is 1, TIM1 counter clock frequency is $f_{CLK} = 170\text{ MHz}$. Setting $\text{PSC} = 0$ and $\text{ARR} = 8499$ yields a period of 8500 clock cycles ($170\text{ MHz} / 8500 = 20\text{ kHz}$).
- **Duty Cycle & PWM Mode**: In PWM Mode 1 with upcounting, the output stays active as long as $\text{CNT} < \text{CCR1}$. A $\text{CCR1}$ of $2125$ achieves an exact $2125 / 8500 = 25\%$ duty cycle.
- **Advanced-Control Requirement**: As TIM1 is an advanced-control timer, `TIM1->BDTR |= TIM_BDTR_MOE` must be set to enable the main output drivers.

