#include "stm32g4xx.h"

void i2c3_controller_init(void)
{
    /* 1. Enable GPIOC and I2C3 peripheral clocks */
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* 2. Configure PC8 (I2C3_SCL) and PC9 (I2C3_SDA):
     *    - Alternate function mode (AF8)
     *    - Open-drain output
     *    - No internal pull-up (external pull-ups to 1.8 V must be used)
     *    - High speed
     */
    GPIOC->MODER &= ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk);
    GPIOC->MODER |=  (2U << GPIO_MODER_MODE8_Pos) | (2U << GPIO_MODER_MODE9_Pos);

    GPIOC->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);

    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk); /* Floating (no pull-up to 3.3 V) */

    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos) | (3U << GPIO_OSPEEDR_OSPEED9_Pos);

    GPIOC->AFR[1] &= ~(GPIO_AFRH_AFSEL8_Msk | GPIO_AFRH_AFSEL9_Msk);
    GPIOC->AFR[1] |=  (8U << GPIO_AFRH_AFSEL8_Pos) | (8U << GPIO_AFRH_AFSEL9_Pos); /* AF8 */

    /* 3. Disable I2C3 before programming configuration registers */
    I2C3->CR1 &= ~I2C_CR1_PE;

    /* 4. Configure timing for 100 kHz Standard Mode from PCLK1 = 170 MHz:
     *    - PRESC  = 15   -> t_PRESC = (15 + 1) / 170 MHz = 94.12 ns
     *    - SCLL   = 53   -> t_LOW   = (53 + 1) * 94.12 ns = 5.08 us (> 4.7 us)
     *    - SCLH   = 51   -> t_HIGH  = (51 + 1) * 94.12 ns = 4.89 us (> 4.0 us)
     *    - SCLDEL = 4    -> t_SU;DAT = 4 * 94.12 ns = 376.5 ns   (> 250 ns)
     *    - SDADEL = 2    -> t_HD;DAT = 2 * 94.12 ns = 188.2 ns   (> 0 ns)
     *    Period = (54 + 52) * 94.12 ns = 9.976 us (~100.2 kHz)
     */
    I2C3->TIMINGR = (15U << I2C_TIMINGR_PRESC_Pos)
                  | (4U  << I2C_TIMINGR_SCLDEL_Pos)
                  | (2U  << I2C_TIMINGR_SDADEL_Pos)
                  | (51U << I2C_TIMINGR_SCLH_Pos)
                  | (53U << I2C_TIMINGR_SCLL_Pos);

    /* 5. Enable I2C3 peripheral */
    I2C3->CR1 |= I2C_CR1_PE;
}
