void tim1_pa8_pwm_init(void)
{
    /* 1. Enable GPIOA and TIM1 peripheral clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PA8 as Alternate Function AF6 (TIM1_CH1) */
    GPIOA->MODER   &= ~GPIO_MODER_MODE8_Msk;
    GPIOA->MODER   |= (2U << GPIO_MODER_MODE8_Pos);        /* Alternate function mode */
    GPIOA->AFR[1]  &= ~(0xFU << ((8U - 8U) * 4U));
    GPIOA->AFR[1]  |=  (6U << ((8U - 8U) * 4U));          /* AF6 = TIM1_CH1 */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);    /* Very high speed */

    /* 3. Configure TIM1 time-base:
     *    TIM1 clock = 170 MHz (PCLK2 = 170 MHz, prescaler multiplier = 1)
     *    f_PWM = 20 kHz -> ARR + 1 = 170,000,000 / 20,000 = 8500 -> ARR = 8499
     *    Duty cycle = 25% -> CCR1 = 8500 * 0.25 = 2125
     */
    TIM1->PSC = 0U;
    TIM1->ARR = 8500U - 1U;
    TIM1->CCR1 = 2125U;

    /* 4. Configure Channel 1: PWM Mode 1, preload enabled, active-high */
    TIM1->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos);             /* OC1M = 0110: PWM mode 1 */
    TIM1->CCMR1 |= TIM_CCMR1_OC1PE;                        /* Output compare 1 preload enable */
    TIM1->CCER  &= ~TIM_CCER_CC1P;                         /* CC1P = 0: Active high */
    TIM1->CCER  |= TIM_CCER_CC1E;                          /* CC1E = 1: Enable OC1 output */

    /* 5. Enable Main Output (MOE, required for advanced-control timers like TIM1) */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* 6. Enable auto-reload preload and start the counter */
    TIM1->CR1 |= TIM_CR1_ARPE;
    TIM1->CR1 |= TIM_CR1_CEN;
}
