void i2c3_master_init(void)
{
    /* 1. Enable GPIOC and I2C3 peripheral clocks */
    RCC->AHB2ENR   |= RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1  |= RCC_APB1ENR1_I2C3EN;

    /* 2. Configure PC8 (SCL) and PC9 (SDA) as Alternate Function AF8 (I2C3) */
    GPIOC->MODER   &= ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk);
    GPIOC->MODER   |=  (2U << GPIO_MODER_MODE8_Pos) | (2U << GPIO_MODER_MODE9_Pos);

    GPIOC->AFR[1]  &= ~((0xFU << ((8U - 8U) * 4U)) | (0xFU << ((9U - 8U) * 4U)));
    GPIOC->AFR[1]  |=  ((8U   << ((8U - 8U) * 4U)) | (8U   << ((9U - 8U) * 4U)));

    /* Open-drain output is required for I2C */
    GPIOC->OTYPER  |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);

    /* High speed */
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos) | (3U << GPIO_OSPEEDR_OSPEED9_Pos);

    /* No internal pull-ups: sensor I/O is 1.8 V while VDD is 3.3 V.
     * Internal pull-ups pull to 3.3 V and must remain disabled.
     * External pull-up resistors to the 1.8 V rail must be present on the board.
     */
    GPIOC->PUPDR   &= ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk);

    /* 3. Configure I2C3 timing:
     *    Source clock = PCLK1 = 170 MHz (default I2C3SEL = 00 in RCC->CCIPR).
     *    Target: Standard Mode (100 kHz, t_scl = 10 us).
     *    PRESC  = 15  -> t_presc = (15 + 1) / 170 MHz = 94.12 ns
     *    SCLDEL = 4   -> t_scldel = (4 + 1) * 94.12 ns = 470.6 ns (min 250 ns)
     *    SDADEL = 2   -> t_sdadel = 2 * 94.12 ns = 188.2 ns (fits 0 <= t_hold <= 3.45 us)
     *    SCLH   = 49  -> t_high = (49 + 1) * 94.12 ns = 4.71 us (min 4.0 us)
     *    SCLL   = 56  -> t_low  = (56 + 1) * 94.12 ns = 5.36 us (min 4.7 us)
     *    Total Period = (50 + 57) * 94.12 ns = 10.07 us -> f_SCL = 99.3 kHz
     */
    I2C3->CR1 &= ~I2C_CR1_PE;  /* Ensure peripheral is disabled before setting TIMINGR */

    I2C3->TIMINGR = (15U << I2C_TIMINGR_PRESC_Pos)
                  | (4U  << I2C_TIMINGR_SCLDEL_Pos)
                  | (2U  << I2C_TIMINGR_SDADEL_Pos)
                  | (49U << I2C_TIMINGR_SCLH_Pos)
                  | (56U << I2C_TIMINGR_SCLL_Pos);

    /* 4. Enable I2C3 peripheral */
    I2C3->CR1 |= I2C_CR1_PE;
}
