#include "stm32g4xx.h"

void Clock_Config_170MHz(void)
{
    /* 1. Enable power interface clock and switch regulator to Range 1 Boost mode */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;
    PWR->CR5 &= ~PWR_CR5_R1MODE; // 0: Range 1 Boost mode (allows operation up to 170 MHz)

    /* 2. Configure Flash latency to 4 wait states (required for 170 MHz in Range 1 Boost mode) */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS)
    {
        /* Wait for Flash latency update */
    }

    /* 3. Configure PLL:
     *    Source: HSI16 (16 MHz)
     *    f_VCO = (f_PLLIN / M) * N = (16 MHz / 4) * 85 = 340 MHz
     *    f_PLLR (SYSCLK) = f_VCO / R = 340 MHz / 2 = 170 MHz
     *    M: 4 (encoded as 4 - 1 = 3)
     *    N: 85
     *    R: 2 (encoded as 00b)
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSI                    |
                   ((4UL - 1UL) << RCC_PLLCFGR_PLLM_Pos)     |
                   (85UL << RCC_PLLCFGR_PLLN_Pos)            |
                   (0UL << RCC_PLLCFGR_PLLR_Pos)             |
                   RCC_PLLCFGR_PLLREN;

    /* 4. Enable Main PLL and wait for lock */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY))
    {
        /* Wait for PLL ready */
    }

    /* 5. Switch system clock to PLL and wait for confirmation */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL)
    {
        /* Wait for system clock switch */
    }
}
