#include "stm32g4xx.h"

void tim3_ch1_pwm_init(void)
{
    /* 1. Enable peripheral clocks for GPIOA (AHB2) and TIM3 (APB1) */
    RCC->AHB2ENR   |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB1ENR1  |= RCC_APB1ENR1_TIM3EN;

    /* 2. Configure PA6 as Alternate Function (AF2 = TIM3_CH1) */
    GPIOA->MODER   &= ~GPIO_MODER_MODE6_Msk;
    GPIOA->MODER   |= (2U << GPIO_MODER_MODE6_Pos);          /* 10: Alternate function mode */
    GPIOA->AFR[0]  &= ~GPIO_AFRL_AFSEL6_Msk;
    GPIOA->AFR[0]  |= (2U << GPIO_AFRL_AFSEL6_Pos);          /* AF2: TIM3_CH1 */
    GPIOA->OSPEEDR |= (2U << GPIO_OSPEEDR_OSPEED6_Pos);      /* 10: High speed */

    /* 3. Configure TIM3 time base for 20 kHz
     *    Timer clock = PCLK1 = 170 MHz (APB1 prescaler is 1)
     *    F_pwm = 170 MHz / ((PSC + 1) * (ARR + 1)) = 20 kHz
     *    PSC = 0 -> ARR + 1 = 170,000,000 / 20,000 = 8500 -> ARR = 8499
     */
    TIM3->PSC = 0U;
    TIM3->ARR = 8499U;

    /* 4. Configure 40 % duty cycle
     *    CCR1 = (ARR + 1) * 0.40 = 8500 * 0.40 = 3400
     */
    TIM3->CCR1 = 3400U;

    /* 5. Configure Channel 1: PWM Mode 1 (OC1M = 0110), preload enable (OC1PE = 1) */
    TIM3->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM3->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* 6. Enable Channel 1 output, active-high polarity (CC1P = 0) */
    TIM3->CCER &= ~TIM_CCER_CC1P;
    TIM3->CCER |= TIM_CCER_CC1E;

    /* 7. Enable Auto-reload preload and force an update event to load shadow registers */
    TIM3->CR1 |= TIM_CR1_ARPE;
    TIM3->EGR |= TIM_EGR_UG;

    /* 8. Start TIM3 counter */
    TIM3->CR1 |= TIM_CR1_CEN;
}
```

### Explanation

* **Pin Mapping:** PA6 is configured to Alternate Function 2 (AF2) for connection to `TIM3_CH1` [DS12288 p.76].
* **Frequency Calculation:** With $PCLK1 = 170\text{ MHz}$ and $PSC = 0$, the timer counts at $170\text{ MHz}$. For a $20\text{ kHz}$ period, the counter requires $\frac{170\text{ MHz}}{20\text{ kHz}} = 8500\text{ counts}$, giving $ARR = 8499$.
* **Duty Cycle:** In PWM Mode 1 (upcounting, active-high), output remains active while $CNT < CCR1$. Setting $CCR1 = 3400$ provides $3400 / 8500 = 40\%$ duty cycle.
* **Preload & Update:** Preload registers ensure glitch-free updates, and writing `TIM_EGR_UG` transfers initial values to shadow registers before enabling the counter.

### Hardware Limitation

In the STM32G4 architecture, **TIM3 is a 16-bit timer with a single timebase** (`PSC` and `ARR`) shared across all four channels [RM0440 p.1159]. 

1. **Shared Period:** Channels running in edge-aligned PWM Mode 1 cannot have different frequencies; TIM3_CH1 and TIM3_CH2 must run at the exact same frequency.
2. **16-bit Overflow:** At $170\text{ MHz}$, a $1\text{ kHz}$ period requires $\frac{170\text{ MHz}}{1\text{ kHz}} = 170{,}000\text{ counts}$, which exceeds the 16-bit limit ($ARR \le 65{,}535$). Achieving $1\text{ kHz}$ on TIM3 requires setting $PSC \ge 2$, which would scale down CH1's frequency as well.

---

### Solution 1: If PA7 must use TIM3_CH2 (frequency compromise)

If both outputs must remain on TIM3, they must share the $1\text{ kHz}$ period ($PSC=169$, $ARR=999$), turning PA6 into a $1\text{ kHz}$ (40% duty) and PA7 into a $1\text{ kHz}$ (50% duty) PWM:

```c
#include "stm32g4xx.h"

void tim3_ch1_ch2_1khz_pwm_init(void)
{
    /* Enable GPIOA and TIM3 clocks */
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN;

    /* Configure PA6 (CH1) and PA7 (CH2) as AF2 (TIM3) */
    GPIOA->MODER   &= ~(GPIO_MODER_MODE6_Msk | GPIO_MODER_MODE7_Msk);
    GPIOA->MODER   |= (2U << GPIO_MODER_MODE6_Pos) | (2U << GPIO_MODER_MODE7_Pos);
    GPIOA->AFR[0]  &= ~(GPIO_AFRL_AFSEL6_Msk | GPIO_AFRL_AFSEL7_Msk);
    GPIOA->AFR[0]  |= (2U << GPIO_AFRL_AFSEL6_Pos) | (2U << GPIO_AFRL_AFSEL7_Pos); /* AF2 */

    /* Timebase for 1 kHz: 170 MHz / ((169 + 1) * (999 + 1)) = 1 kHz */
    TIM3->PSC = 169U;
    TIM3->ARR = 999U;

    /* CH1 = 40% (400/1000), CH2 = 50% (500/1000) */
    TIM3->CCR1 = 400U;
    TIM3->CCR2 = 500U;

    /* PWM Mode 1 and preload on CH1 and CH2 */
    TIM3->CCMR1 = (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE |
                  (6U << TIM_CCMR1_OC2M_Pos) | TIM_CCMR1_OC2PE;

    /* Enable CH1 and CH2 outputs, active-high */
    TIM3->CCER |= TIM_CCER_CC1E | TIM_CCER_CC2E;

    TIM3->CR1  |= TIM_CR1_ARPE;
    TIM3->EGR  |= TIM_EGR_UG;
    TIM3->CR1  |= TIM_CR1_CEN;
}
```

---

### Solution 2: Preserving 20 kHz on PA6 via independent timer on PA7 (TIM17_CH1)

PA7 also maps to **AF8 (TIM17_CH1)** [DS12288 p.76]. TIM17 provides a separate timebase, allowing PA6 to remain at $20\text{ kHz}$ while PA7 runs at $1\text{ kHz}$:

```c
#include "stm32g4xx.h"

void buzzer_tim17_ch1_1khz_init(void)
{
    /* Enable TIM17 clock (APB2) and GPIOA (AHB2) */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM17EN;

    /* Configure PA7 as Alternate Function 8 (TIM17_CH1) */
    GPIOA->MODER  &= ~GPIO_MODER_MODE7_Msk;
    GPIOA->MODER  |= (2U << GPIO_MODER_MODE7_Pos);
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL7_Msk;
    GPIOA->AFR[0] |= (8U << GPIO_AFRL_AFSEL7_Pos);           /* AF8: TIM17_CH1 */

    /* 1 kHz time base: 170 MHz / ((169 + 1) * (999 + 1)) = 1 kHz */
    TIM17->PSC = 169U;
    TIM17->ARR = 999U;
    TIM17->CCR1 = 500U;                                       /* 50% duty cycle */

    /* PWM Mode 1, preload enable */
    TIM17->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM17->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Enable Channel 1 output */
    TIM17->CCER |= TIM_CCER_CC1E;

    /* BDTR MOE must be set for TIM16/TIM17 outputs to be enabled */
    TIM17->BDTR |= TIM_BDTR_MOE;

    TIM17->CR1  |= TIM_CR1_ARPE;
    TIM17->EGR  |= TIM_EGR_UG;
    TIM17->CR1  |= TIM_CR1_CEN;
}
