#include "stm32g4xx.h"

void usart3_init(void)
{
    /* 1. Enable peripheral clocks for GPIOB (AHB2) and USART3 (APB1) */
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOBEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART3EN;

    /* Ensure USART3 clock source is PCLK1 (CCIPR bits 5:4 = 00, reset state) */
    RCC->CCIPR &= ~RCC_CCIPR_USART3SEL_Msk;

    /* 2. Configure PB10 (TX) and PB11 (RX) to Alternate Function AF7 (USART3) */
    GPIOB->MODER &= ~(GPIO_MODER_MODE10_Msk | GPIO_MODER_MODE11_Msk);
    GPIOB->MODER |= (2U << GPIO_MODER_MODE10_Pos) | (2U << GPIO_MODER_MODE11_Pos);

    /* AF7: AFSEL10 = 7 (AFRH bits 11:8), AFSEL11 = 7 (AFRH bits 15:12) */
    GPIOB->AFR[1] &= ~(GPIO_AFRH_AFSEL10_Msk | GPIO_AFRH_AFSEL11_Msk);
    GPIOB->AFR[1] |= (7U << GPIO_AFRH_AFSEL10_Pos) | (7U << GPIO_AFRH_AFSEL11_Pos);

    /* Output push-pull, high speed, pull-up on RX line */
    GPIOB->OSPEEDR |= (2U << GPIO_OSPEEDR_OSPEED10_Pos) | (2U << GPIO_OSPEEDR_OSPEED11_Pos);
    GPIOB->PUPDR   |= (1U << GPIO_PUPDR_PUPD11_Pos);

    /* 3. Configure frame format: 8 data bits (M[1:0] = 00), 1 stop bit (STOP[1:0] = 00),
     *    oversampling by 16 (OVER8 = 0), no parity (PCE = 0)
     */
    USART3->CR1 &= ~(USART_CR1_M0 | USART_CR1_M1 | USART_CR1_PCE | USART_CR1_OVER8);
    USART3->CR2 &= ~USART_CR2_STOP_Msk;

    /* 4. Write Baud Rate Register while UE = 0
     *    USARTDIV = f_CK / Baud = 170,000,000 / 115,200 = 1475.694
     *    Rounding to nearest integer: BRR = 1476 (0x05C4)
     *    Actual baud = 170 MHz / 1476 = 115,176.15 baud (~0.02% error)
     */
    USART3->BRR = 1476U;

    /* 5. Enable transmitter, receiver, and USART peripheral */
    USART3->CR1 |= USART_CR1_TE | USART_CR1_RE;
    USART3->CR1 |= USART_CR1_UE;
}

void usart3_write_char(uint8_t ch)
{
    /* Wait until Transmit Data Register Empty (TXE / TXFNF) flag is set */
    while (!(USART3->ISR & USART_ISR_TXE_TXFNF))
        ;
    USART3->TDR = ch;
}

uint8_t usart3_read_char(void)
{
    /* Wait until Read Data Register Not Empty (RXNE / RXFNE) flag is set */
    while (!(USART3->ISR & USART_ISR_RXNE_RXFNE))
        ;
    return (uint8_t)(USART3->RDR & 0xFFU);
}
```

### Explanation

* **Pin Multiplexing:** PB10 and PB11 map to AF7 for `USART3_TX` and `USART3_RX` [DS12288 p.78].
* **Clock Source & Baud Rate:** USART3 defaults to PCLK1 ($170\text{ MHz}$) via `RCC->CCIPR`. With 16× oversampling (`OVER8 = 0`), the formula is $BRR = \text{round}(f_{CK} / \text{Baud}) = \text{round}(170{,}000{,}000 / 115{,}200) = 1476$ [RM0440 p.1384].
* **Execution Sequence:** As specified, `USART3->BRR` is configured before asserting `USART_CR1_UE` [RM0440 p.1383].

