int main(void)
{
    /* =========================================================================
     * 1. Enable Peripheral Clocks
     * ========================================================================= */
    /* GPIOA, GPIOB on AHB2 */
    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOBEN;
    /* TIM3, USART3 on APB1 */
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN | RCC_APB1ENR1_USART3EN;
    /* TIM17 on APB2 */
    RCC->APB2ENR  |= RCC_APB2ENR_TIM17EN;

    /* Ensure USART3 clock source is PCLK1 (170 MHz) */
    RCC->CCIPR   &= ~RCC_CCIPR_USART3SEL_Msk;

    /* =========================================================================
     * 2. GPIO Pin Configuration
     * ========================================================================= */
    /* PA6 -> AF2 (TIM3_CH1), PA7 -> AF8 (TIM17_CH1) */
    GPIOA->MODER   &= ~(GPIO_MODER_MODE6_Msk | GPIO_MODER_MODE7_Msk);
    GPIOA->MODER   |= (2U << GPIO_MODER_MODE6_Pos) | (2U << GPIO_MODER_MODE7_Pos);
    GPIOA->AFR[0]  &= ~(GPIO_AFRL_AFSEL6_Msk | GPIO_AFRL_AFSEL7_Msk);
    GPIOA->AFR[0]  |= (2U << GPIO_AFRL_AFSEL6_Pos) | (8U << GPIO_AFRL_AFSEL7_Pos);
    GPIOA->OSPEEDR |= (2U << GPIO_OSPEEDR_OSPEED6_Pos) | (2U << GPIO_OSPEEDR_OSPEED7_Pos);

    /* PB10 -> AF7 (USART3_TX), PB11 -> AF7 (USART3_RX) */
    GPIOB->MODER   &= ~(GPIO_MODER_MODE10_Msk | GPIO_MODER_MODE11_Msk);
    GPIOB->MODER   |= (2U << GPIO_MODER_MODE10_Pos) | (2U << GPIO_MODER_MODE11_Pos);
    GPIOB->AFR[1]  &= ~(GPIO_AFRH_AFSEL10_Msk | GPIO_AFRH_AFSEL11_Msk);
    GPIOB->AFR[1]  |= (7U << GPIO_AFRH_AFSEL10_Pos) | (7U << GPIO_AFRH_AFSEL11_Pos);
    GPIOB->OSPEEDR |= (2U << GPIO_OSPEEDR_OSPEED10_Pos) | (2U << GPIO_OSPEEDR_OSPEED11_Pos);
    GPIOB->PUPDR   |= (1U << GPIO_PUPDR_PUPD11_Pos);

    /* =========================================================================
     * 3. TIM3: PA6 Status LED (20 kHz, 40 % Duty Cycle)
     *    Timebase: 170 MHz / ((0 + 1) * (8499 + 1)) = 20 kHz
     * ========================================================================= */
    TIM3->PSC   = 0U;
    TIM3->ARR   = 8499U;
    TIM3->CCR1  = 3400U;                                      /* 8500 * 0.40 */
    TIM3->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM3->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE; /* PWM Mode 1 */
    TIM3->CCER  &= ~TIM_CCER_CC1P;                           /* Active-high */
    TIM3->CCER  |= TIM_CCER_CC1E;
    TIM3->CR1   |= TIM_CR1_ARPE;
    TIM3->EGR   |= TIM_EGR_UG;
    TIM3->CR1   |= TIM_CR1_CEN;

    /* =========================================================================
     * 4. TIM17: PA7 Buzzer (1 kHz, 50 % Duty Cycle)
     *    Timebase: 170 MHz / ((169 + 1) * (999 + 1)) = 1 kHz
     * ========================================================================= */
    TIM17->PSC   = 169U;
    TIM17->ARR   = 999U;
    TIM17->CCR1  = 500U;                                      /* 1000 * 0.50 */
    TIM17->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM17->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE; /* PWM Mode 1 */
    TIM17->CCER  &= ~TIM_CCER_CC1P;                          /* Active-high */
    TIM17->CCER  |= TIM_CCER_CC1E;
    TIM17->BDTR  |= TIM_BDTR_MOE;                            /* Main Output Enable */
    TIM17->CR1   |= TIM_CR1_ARPE;
    TIM17->EGR   |= TIM_EGR_UG;
    TIM17->CR1   |= TIM_CR1_CEN;

    /* =========================================================================
     * 5. USART3: PB10 (TX), PB11 (RX) (115200 Baud, 8N1)
     *    BRR = 170,000,000 / 115,200 = 1476 (written before UE = 1)
