    /* Push-pull output (OTYPER bit 6 = 0, default), no pull-up/pull-down */
    GPIOA->PUPDR &= ~GPIO_PUPDR_PUPD6_Msk;

    /* Map PA6 to Alternate Function 2 (TIM3_CH1) */
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL6_Msk;
    GPIOA->AFR[0] |= (2U << GPIO_AFRL_AFSEL6_Pos);

    /* 3. Configure TIM3 time base for 1 kHz frequency
     *    Timer clock = 170 MHz (PCLK1 prescaler = 1, so timer multiplier = 1)
     *    Target frequency: f = 170 MHz / ((PSC + 1) * (ARR + 1)) = 1 kHz
     *    Choose PSC = 169 -> counting clock = 170 MHz / 170 = 1 MHz
     *    ARR = 1000 - 1 = 999 -> 1 MHz / 1000 = 1 kHz
     */
    TIM3->PSC = 170U - 1U;
    TIM3->ARR = 1000U - 1U;

    /* 4. Set 50% duty cycle: CCR1 = 500 */
    TIM3->CCR1 = 500U;

    /* 5. Configure Channel 1:
     *    - Output mode (CC1S = 00 in CCMR1)
     *    - Output Compare 1 Preload Enable (OC1PE = 1)
     *    - PWM Mode 1: active while CNT < CCR1 (OC1M[3:0] = 0110b)
     */
    TIM3->CCMR1 &= ~(TIM_CCMR1_CC1S_Msk | TIM_CCMR1_OC1M_Msk);
    TIM3->CCMR1 |= (TIM_CCMR1_OC1PE | (6U << TIM_CCMR1_OC1M_Pos));

    /* 6. Configure Channel 1 Output Polarity and Enable:
     *    - Active high: CC1P = 0
     *    - Enable output: CC1E = 1
     */
    TIM3->CCER &= ~TIM_CCER_CC1P;
    TIM3->CCER |= TIM_CCER_CC1E;

    /* 7. Enable Auto-Reload Preload (ARPE) and edge-aligned upcounting (CMS = 00, DIR = 0) */
    TIM3->CR1 |= TIM_CR1_ARPE;

    /* 8. Generate an update event to latch PSC, ARR, and CCR1 values immediately */
    TIM3->EGR = TIM_EGR_UG;

    /* 9. Enable TIM3 counter */
    TIM3->CR1 |= TIM_CR1_CEN;
