     *    With OVER8 = 0 (oversampling by 16):
     *    USARTDIV = fCK / Baud = 170,000,000 / 115,200 = 1475.694...
     *    BRR = round(170,000,000 / 115,200) = 1476 (0x05C4)
     */
    USART3->BRR = 1476;

    /* 4. Configure framing in CR1 and CR2:
     *    - 8 data bits: M1:M0 = 00 (in CR1, reset state)
     *    - Parity control disabled: PCE = 0 (in CR1, reset state)
     *    - Oversampling by 16: OVER8 = 0 (in CR1, reset state)
     *    - 1 stop bit: STOP[1:0] = 00 (in CR2, reset state)
     *    - Transmitter enable: TE = 1
     *    - Receiver enable: RE = 1
     */
    USART3->CR1 &= ~(USART_CR1_M1 | USART_CR1_M0 | USART_CR1_PCE | USART_CR1_OVER8);
    USART3->CR2 &= ~USART_CR2_STOP_Msk;
    USART3->CR1 |= (USART_CR1_TE | USART_CR1_RE);

    /* 5. Enable USART */
    USART3->CR1 |= USART_CR1_UE;
}

