#include "stm32g4xx.h"

void usart1_init(void)
{
    /* 1. Enable peripheral clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;    /* Enable GPIOA clock */
    RCC->APB2ENR |= RCC_APB2ENR_USART1EN;   /* Enable USART1 clock */

    /* 2. Configure GPIO pins PA2 (TX) and PA3 (RX) */
    /* Note: AF7 on PA2/PA3 routes to USART2, not USART1. */
    GPIOA->MODER &= ~(GPIO_MODER_MODE2_Msk | GPIO_MODER_MODE3_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE2_Pos) | (2U << GPIO_MODER_MODE3_Pos); /* AF mode (10b) */

    GPIOA->AFR[0] &= ~(GPIO_AFRL_AFSEL2_Msk | GPIO_AFRL_AFSEL3_Msk);
    GPIOA->AFR[0] |= (7U << GPIO_AFRL_AFSEL2_Pos) | (7U << GPIO_AFRL_AFSEL3_Pos); /* AF7 */

    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED2_Pos); /* High speed on TX */
    GPIOA->PUPDR   |= (1U << GPIO_PUPDR_PUPD3_Pos);     /* Pull-up on RX */

    /* 3. Configure USART1: 8 data bits, 1 stop bit, no parity, oversampling by 16 */
    /* Reset values of CR1: M[1:0] = 00 (8 data bits), PCE = 0 (no parity), OVER8 = 0 (16x oversampling) */
    /* Reset values of CR2: STOP[1:0] = 00 (1 stop bit) */
    USART1->CR1 = 0U;
    USART1->CR2 = 0U;
    USART1->CR3 = 0U;

    /* 4. Set Baud Rate: BRR = fCK / Baud = 170,000,000 / 115200 = 1475.69 -> 1476 */
    USART1->BRR = 1476U;

    /* 5. Enable Transmitter and Receiver */
    USART1->CR1 |= (USART_CR1_TE | USART_CR1_RE);

    /* 6. Enable USART */
    USART1->CR1 |= USART_CR1_UE;
}
