    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOCEN | RCC_AHB2ENR_GPIOBEN;
    RCC->APB2ENR |= RCC_APB2ENR_USART1EN;

    /* 2. Configure PC4 (TX) as Alternate Function AF7 (3.3V out is 5V TTL-compatible) */
    GPIOC->MODER &= ~GPIO_MODER_MODE4_Msk;
    GPIOC->MODER |= (2U << GPIO_MODER_MODE4_Pos);
    GPIOC->AFR[0] &= ~GPIO_AFRL_AFSEL4_Msk;
    GPIOC->AFR[0] |= (7U << GPIO_AFRL_AFSEL4_Pos);
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED4_Pos);

    /* 3. Configure PB7 (RX) as Alternate Function AF7 (PB7 is 5V-tolerant FT pin) */
    GPIOB->MODER &= ~GPIO_MODER_MODE7_Msk;
    GPIOB->MODER |= (2U << GPIO_MODER_MODE7_Pos);
    GPIOB->AFR[0] &= ~GPIO_AFRL_AFSEL7_Msk;
    GPIOB->AFR[0] |= (7U << GPIO_AFRL_AFSEL7_Pos);
    /* Ensure no internal pull-up/down interferes with the 5V drive */
    GPIOB->PUPDR &= ~GPIO_PUPDR_PUPD7_Msk;

    /* 4. Configure USART1 frame format: 8N1, oversampling by 16 */
    USART1->CR1 = 0;
    USART1->CR2 = 0;
    USART1->CR3 = 0;

    /* 5. Set Baud Rate to 230400 bps with f_CK = 170 MHz */
    USART1->BRR = (170000000U + (230400U / 2U)) / 230400U; /* 738 */

    /* 6. Enable Transmitter, Receiver, and USART peripheral */
    USART1->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;
