void tim1_pa8_pwm_init(void)
{
    /* 1. Enable peripheral clocks for GPIOA (AHB2) and TIM1 (APB2) [STM32G474_RM0440 p.1265] */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB2ENR |= RCC_APB2ENR_TIM1EN;

    /* 2. Configure PA8 as Alternate Function AF6 (TIM1_CH1) [STM32G474_Datasheet p.62, STM32G474_RM0440 p.1265] */
    /* Set MODER8 to Alternate Function mode (0b10) */
    GPIOA->MODER &= ~GPIO_MODER_MODE8_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE8_Pos);

    /* Set high-speed output on PA8 */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);

    /* Configure Alternate Function 6 in AFR[1] (AFRH) for pin 8 */
    GPIOA->AFR[1] &= ~GPIO_AFRH_AFSEL8_Msk;
    GPIOA->AFR[1] |= (6U << GPIO_AFRH_AFSEL8_Pos);

    /* 3. Configure TIM1 timing for 20 kHz PWM with 25% duty cycle [STM32G474_RM0440 p.1265]
     * Timer clock = PCLK2 = 170 MHz (APB2 prescaler = 1).
     * Counter frequency = 170 MHz / (PSC + 1) = 170 MHz (PSC = 0).
     * PWM period = 170,000,000 Hz / 20,000 Hz = 8,500 timer ticks.
     * ARR = Period - 1 = 8500 - 1 = 8499.
     * CCR1 = 8500 * 25% = 2125 ticks.
     */
    TIM1->PSC  = 0U;
    TIM1->ARR  = 8500U - 1U;
    TIM1->CCR1 = 2125U;

    /* 4. Configure Channel 1: PWM Mode 1 (OC1M = 0110b), enable OC1 preload [STM32G474_RM0440 p.1265] */
    TIM1->CCMR1 &= ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk);
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* 5. Set output polarity to active-high (CC1P = 0) and enable output (CC1E = 1) [STM32G474_RM0440 p.1265] */
    TIM1->CCER &= ~TIM_CCER_CC1P;
