     *    Timer clock = PCLK2 = 170 MHz (APB2 prescaler = 1).
     *    f_PWM = TIM1_CLK / ((PSC + 1) * (ARR + 1))
     *    20000 = 170000000 / ((0 + 1) * (8499 + 1))
     */
    TIM1->PSC = 0U;
    TIM1->ARR = 8499U;

    /* 5. Set duty cycle to 25 %:
     *    In PWM Mode 1 (up-counting), high duration = CCR1 counts.
