#include "stm32g4xx.h"

int main(void) {
    /* 1. Select SYSCLK (170 MHz) as I2C3 kernel clock source in RCC->CCIPR:
     *    I2C3SEL[1:0] = 01 (0x1) -> System clock selected as I2C3 clock.
     */
    RCC->CCIPR = (RCC->CCIPR & ~RCC_CCIPR_I2C3SEL) | (1UL << RCC_CCIPR_I2C3SEL_Pos);

    /* 2. Enable peripheral clocks for GPIOA, GPIOC, and I2C3:
     *    - GPIOA and GPIOC via RCC->AHB2ENR
     *    - I2C3 via RCC->APB1ENR1
     */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* 3. Configure PA8 (I2C3_SCL, AF2) as Open-Drain Alternate Function:
     *    - MODER8 = 10 (Alternate Function)
     *    - OTYPER8 = 1 (Open-Drain)
     *    - OSPEEDR8 = 11 (Very High Speed)
     *    - PUPDR8 = 01 (Pull-up enabled)
     *    - AFR[1] (AFRH) AFSEL8 = 2 (AF2: I2C3_SCL)
     */
    GPIOA->MODER = (GPIOA->MODER & ~GPIO_MODER_MODE8_Msk) | (2UL << GPIO_MODER_MODE8_Pos);
    GPIOA->OTYPER |= GPIO_OTYPER_OT8;
    GPIOA->OSPEEDR |= (3UL << GPIO_OSPEEDR_OSPEED8_Pos);
    GPIOA->PUPDR = (GPIOA->PUPDR & ~GPIO_PUPDR_PUPD8_Msk) | (1UL << GPIO_PUPDR_PUPD8_Pos);
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~GPIO_AFRH_AFSEL8_Msk) | (2UL << GPIO_AFRH_AFSEL8_Pos);

    /* 4. Configure PC9 (I2C3_SDA, AF8) as Open-Drain Alternate Function:
     *    - MODER9 = 10 (Alternate Function)
     *    - OTYPER9 = 1 (Open-Drain)
     *    - OSPEEDR9 = 11 (Very High Speed)
     *    - PUPDR9 = 01 (Pull-up enabled)
     *    - AFR[1] (AFRH) AFSEL9 = 8 (AF8: I2C3_SDA)
     */
    GPIOC->MODER = (GPIOC->MODER & ~GPIO_MODER_MODE9_Msk) | (2UL << GPIO_MODER_MODE9_Pos);
    GPIOC->OTYPER |= GPIO_OTYPER_OT9;
    GPIOC->OSPEEDR |= (3UL << GPIO_OSPEEDR_OSPEED9_Pos);
    GPIOC->PUPDR = (GPIOC->PUPDR & ~GPIO_PUPDR_PUPD9_Msk) | (1UL << GPIO_PUPDR_PUPD9_Pos);
    GPIOC->AFR[1] = (GPIOC->AFR[1] & ~GPIO_AFRH_AFSEL9_Msk) | (8UL << GPIO_AFRH_AFSEL9_Pos);

    /* 5. Configure I2C3 TIMINGR while PE is cleared:
     *    With fI2CCLK = 170 MHz:
