    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);
    /* No pull-up, no pull-down (00b) */
    GPIOA->PUPDR &= ~GPIO_PUPDR_PUPD8_Msk;
    /* Route to AF6 (TIM1_CH1) in AFRH (AFR[1]) */
    GPIOA->AFR[1] = (GPIOA->AFR[1] & ~GPIO_AFRH_AFSEL8_Msk) | (6U << GPIO_AFRH_AFSEL8_Pos);

    /* -------------------------------------------------------------------------
     * 3. Configure PC8 (I2C3_SCL) and PC9 (I2C3_SDA) (Alternate Function 8)
     * ------------------------------------------------------------------------- */
    /* Mode: Alternate Function (10b) */
    GPIOC->MODER = (GPIOC->MODER & ~(GPIO_MODER_MODE8_Msk | GPIO_MODER_MODE9_Msk)) |
                   (2U << GPIO_MODER_MODE8_Pos) |
                   (2U << GPIO_MODER_MODE9_Pos);
    /* Output type: Open-Drain (1b) for I2C */
    GPIOC->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);
    /* Output speed: Very High Speed (11b) */
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos) |
                      (3U << GPIO_OSPEEDR_OSPEED9_Pos);
    /* No internal pull-up / pull-down (external pull-ups to 3.3V on bus side) */
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk);
    /* Route PC8 and PC9 to AF8 (I2C3) in AFRH (AFR[1]) */
    GPIOC->AFR[1] = (GPIOC->AFR[1] & ~(GPIO_AFRH_AFSEL8_Msk | GPIO_AFRH_AFSEL9_Msk)) |
                    (8U << GPIO_AFRH_AFSEL8_Pos) |
                    (8U << GPIO_AFRH_AFSEL9_Pos);

    /* -------------------------------------------------------------------------
     * 4. Configure TIM1: 20 kHz PWM, 25% Duty Cycle on Channel 1
     * ------------------------------------------------------------------------- */
    /* Timer clock = 170 MHz. Prescaler = 0 -> timer counter runs at 170 MHz */
    TIM1->PSC = 0U;
    /* Period = 170 MHz / 20 kHz - 1 = 8499 */
    TIM1->ARR = 8499U;
    /* Duty cycle = 25% of (8499 + 1) = 2125 */
    TIM1->CCR1 = 2125U;

    /* Channel 1: Output compare, PWM mode 1 (OC1M = 0110b), Preload enable (OC1PE = 1) */
    TIM1->CCMR1 = (TIM1->CCMR1 & ~(TIM_CCMR1_CC1S_Msk | TIM_CCMR1_OC1M_Msk | TIM_CCMR1_OC1M_3)) |
                  TIM_CCMR1_OC1PE |
                  (6U << TIM_CCMR1_OC1M_Pos);

    /* Enable Auto-reload preload (ARPE) */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* Enable Channel 1 output, active-high polarity */
    TIM1->CCER &= ~TIM_CCER_CC1P;
    TIM1->CCER |= TIM_CCER_CC1E;

    /* Main Output Enable (MOE) - required for TIM1 advanced-control timer */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* Generate update event to load preload values into shadow registers */
    TIM1->EGR |= TIM_EGR_UG;

    /* Start TIM1 counter */
    TIM1->CR1 |= TIM_CR1_CEN;

    /* -------------------------------------------------------------------------
     * 5. Configure I2C3 Controller (Standard Mode, 100 kHz)
     * ------------------------------------------------------------------------- */
    /* Ensure I2C3 is disabled before modifying TIMINGR */
    I2C3->CR1 &= ~I2C_CR1_PE;

    /* Timing calculation with PCLK1 = 170 MHz:
     * - PRESC  = 15  -> tPRESC = (15 + 1) / 170 MHz = 94.12 ns
     * - SCLDEL = 4   -> tSCLDEL = (4 + 1) * tPRESC = 470.6 ns (>= 250 ns)
     * - SDADEL = 2   -> tSDADEL = 2 * tPRESC = 188.2 ns
     * - SCLH   = 49  -> tSCLH   = (49 + 1) * tPRESC = 4.706 us (>= 4.0 us)
     * - SCLL   = 55  -> tSCLL   = (55 + 1) * tPRESC = 5.271 us (>= 4.7 us)
     * Resulting SCL period ~ 10.0 us -> 100 kHz standard mode.
     */
    I2C3->TIMINGR = (15U << I2C_TIMINGR_PRESC_Pos)  |
                    (4U  << I2C_TIMINGR_SCLDEL_Pos) |
                    (2U  << I2C_TIMINGR_SDADEL_Pos) |
                    (49U << I2C_TIMINGR_SCLH_Pos)   |
                    (55U << I2C_TIMINGR_SCLL_Pos);

    /* Enable I2C3 peripheral */
    I2C3->CR1 |= I2C_CR1_PE;

    /* -------------------------------------------------------------------------
     * Main Loop
     * ------------------------------------------------------------------------- */
    while (1)
    {
        /* Ready for application tasks / sensor communication */
    }
}
