 * @brief Configure STM32G474 clock system to 170 MHz from HSI16 in Range 1 Boost Mode.
 *        Operating VDD: 3.6 V (recommended operating limit 1.71 V - 3.6 V [STM32G474_Datasheet p.84]).
 */
void SystemClock_Config_170MHz(void)
{
    /* 1. Ensure internal HSI16 oscillator is enabled and ready [STM32G474_RM0440 p.287] */
    RCC->CR |= RCC_CR_HSION;
    while (!(RCC->CR & RCC_CR_HSIRDY));

    /* 2. Enable Power Controller interface clock [STM32G474_RM0440 p.309] */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* 3. Configure Flash latency to 4 wait states (for 170 MHz in Range 1 Boost Mode [STM32G474_RM0440 p.98])
          Enable Prefetch Buffer, Instruction Cache, and Data Cache [STM32G474_RM0440 p.130] */
    FLASH->ACR = FLASH_ACR_LATENCY_4WS | FLASH_ACR_PRFTEN | FLASH_ACR_ICEN | FLASH_ACR_DCEN;
    while ((FLASH->ACR & FLASH_ACR_LATENCY_Msk) != FLASH_ACR_LATENCY_4WS);

    /* 4. Set AHB prescaler to /2 (transition state before boost mode and high frequency [STM32G474_RM0440 p.233, p.280]) */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE_Msk) | RCC_CFGR_HPRE_DIV2;

    /* 5. Switch to Range 1 Boost Mode: clear R1MODE in PWR_CR5 [STM32G474_RM0440 p.233, p.267] */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 6. Configure Main PLL:
          - Clock source: HSI16 (16 MHz) [STM32G474_Datasheet p.120]
          - PLLM = 4: f_vco_in = 16 MHz / 4 = 4 MHz (within 2.66 - 16 MHz [STM32G474_Datasheet p.123])
          - PLLN = 85: f_vco = 4 MHz * 85 = 340 MHz (within 96 - 344 MHz [STM32G474_Datasheet p.123])
          - PLLR = 2: f_pll_r = 340 MHz / 2 = 170 MHz [STM32G474_Datasheet p.123]
          - Enable PLL "R" clock output (PLLREN)
    */
    RCC->CR &= ~RCC_CR_PLLON;
    while (RCC->CR & RCC_CR_PLLRDY);

    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSI |
                   (3U << RCC_PLLCFGR_PLLM_Pos) |        /* PLLM = 4 (register field value 3) */
                   (85U << RCC_PLLCFGR_PLLN_Pos) |       /* PLLN = 85 */
                   (0U << RCC_PLLCFGR_PLLR_Pos) |        /* PLLR = 2 (register field value 0) */
                   RCC_PLLCFGR_PLLREN;

    /* Enable PLL and wait for lock [STM32G474_RM0440 p.278] */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    /* 7. Switch SYSCLK to PLL [STM32G474_RM0440 p.279, p.289] */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW_Msk) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS_Msk) != RCC_CFGR_SWS_PLL);

    /* 8. Wait at least 1 us in transition state before restoring AHB prescaler [STM32G474_RM0440 p.233, p.280] */
    for (volatile uint32_t i = 0; i < 50; i++) {
        __NOP();
    }

    /* 9. Set AHB prescaler to /1 -> HCLK = 170 MHz [STM32G474_RM0440 p.233, p.290] */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE_Msk) | RCC_CFGR_HPRE_DIV1;
    while ((RCC->CFGR & RCC_CFGR_HPRE_Msk) != RCC_CFGR_HPRE_DIV1);

    /* 10. Configure APB1 and APB2 prescalers to /1 (PCLK1 = 170 MHz, PCLK2 = 170 MHz) */
    RCC->CFGR &= ~(RCC_CFGR_PPRE1_Msk | RCC_CFGR_PPRE2_Msk);
}
