    GPIOA->MODER &= ~GPIO_MODER_MODE0_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE0_Pos);          /* 10: Alternate function */
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL0_Msk;
    GPIOA->AFR[0] |= (1U << GPIO_AFRL_AFSEL0_Pos);          /* AF1 for TIM2_CH1 */

