    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM2EN;

    /* 4. Configure TIM2 time base:
     *    TIM2 counter clock = APB1 timer clock = 170 MHz (APB1 prescaler = 1 -> x1).
     *    Target PWM frequency = 1 kHz.
     *    Counter period = 170 MHz / 1 kHz = 170,000 counts.
     *    TIM2 is a 32-bit timer, so PSC = 0 and ARR = 169999.
     *    For 50% duty cycle: CCR1 = 170,000 / 2 = 85000.
     */
    TIM2->PSC = 0U;
    TIM2->ARR = 169999U;
    TIM2->CCR1 = 85000U;

    /* 5. Configure channel 1 for PWM mode 1 with preload enabled:
     *    OC1M = 0110b (PWM mode 1: active while TIM2_CNT < TIM2_CCR1)
     *    OC1PE = 1 (Preload enable)
     */
    TIM2->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM2->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* 6. Enable channel 1 output on pin, active-high polarity (CC1P = 0) */
    TIM2->CCER &= ~TIM_CCER_CC1P;
    TIM2->CCER |= TIM_CCER_CC1E;

    /* 7. Enable Auto-Reload Preload (ARPE) and start counter (CEN) */
    TIM2->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;

    /* 8. Trigger update event to transfer preload values to shadow registers */
    TIM2->EGR |= TIM_EGR_UG;

