    /* Enable TIM2 peripheral clock */
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM2EN;

    /*
     * Configure TIM2 frequency and duty cycle:
     * Clock source: PCLK1 = 170 MHz (APB1 prescaler = 1, so timer clock = 170 MHz)
     * Target frequency = 1 kHz (1000 Hz)
     * Target duty cycle = 50 %
     *
     * TIM2 is a 32-bit timer:
     * f_pwm = f_tim / ((PSC + 1) * (ARR + 1))
     * With PSC = 0: ARR = (170,000,000 / 1000) - 1 = 169999
     * Duty cycle = CCR1 / (ARR + 1) = 85000 / 170000 = 50.0 %
     */
    TIM2->PSC = 0;
    TIM2->ARR = 169999;
    TIM2->CCR1 = 85000;

