     *    In Range 1 Boost Mode, HCLK up to 170 MHz (136 < HCLK <= 170 MHz)
     *    requires 4 wait states (LATENCY = 4, 5 CPU cycles) [STM32G474_RM0440 p.98].
     */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS) {
        /* Wait until the new number of wait states is active */
    }

    /* 4. Enable HSE oscillator and wait for it to be stable */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY)) {
        /* Busy-wait until HSE is ready */
    }

    /* 5. Configure Main PLL:
     *    - Source: HSE (8 MHz) -> PLLSRC = 3
     *    - PLLM: /1 (encoded as 0) -> fVCO_IN = 8 MHz / 1 = 8 MHz (valid: 2.66 - 16 MHz) [STM32G474_Datasheet p.123]
     *    - PLLN: *42 (encoded as 42) -> fVCO_OUT = 8 MHz * 42 = 336 MHz (valid: 96 - 344 MHz) [STM32G474_Datasheet p.123]
     *    - PLLR: /2 (encoded as 0) -> fPLL_R = 336 MHz / 2 = 168 MHz
     *    - PLLREN: Enable main PLL 'R' output clock
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE |
                   (0 << RCC_PLLCFGR_PLLM_Pos) |
                   (42 << RCC_PLLCFGR_PLLN_Pos) |
                   (0 << RCC_PLLCFGR_PLLR_Pos) |
                   RCC_PLLCFGR_PLLREN;

    /* 6. Enable Main PLL and wait for PLLRDY */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
        /* Busy-wait until PLL is locked */
    }

    /* 7. Safe clock switching sequence [STM32G474_RM0440 p.279]:
     *    When switching from HSI16/HSE to PLL with HCLK > 80 MHz, use an
     *    intermediate state by setting AHB prescaler HPRE = /2 (HCLK = 84 MHz).
