    // 2. Configure PC0 pin as Alternate Function (AF2 = TIM1_CH1)
    // Clear and set MODER0 to Alternate Function mode ('10')
    GPIOC->MODER &= ~GPIO_MODER_MODE0_Msk;
    GPIOC->MODER |= (2U << GPIO_MODER_MODE0_Pos);

    // Map PC0 to AF2 in AFRL (AFRL0 = 2)
    GPIOC->AFR[0] &= ~GPIO_AFRL_AFSEL0_Msk;
    GPIOC->AFR[0] |= (2U << GPIO_AFRL_AFSEL0_Pos);

    // Set high output speed for PC0
    GPIOC->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED0_Pos);

    // 3. Configure TIM1 time-base for 20 kHz PWM
    // Counter clock frequency = 170 MHz / (PSC + 1) = 170 MHz (with PSC = 0)
    // f_PWM = 170 MHz / ((PSC + 1) * (ARR + 1)) = 170,000,000 / (1 * 8500) = 20,000 Hz
    TIM1->PSC = 0;
    TIM1->ARR = 8499;

    // 4. Set duty cycle to 25 %:
    // Duty = CCR1 / (ARR + 1) = 2125 / 8500 = 0.25 (25 %)
    TIM1->CCR1 = 2125;

    // 5. Configure channel 1 for PWM Mode 1 with preload enabled
    // OC1M = 0110b (PWM Mode 1: active while CNT < CCR1, inactive otherwise)
    TIM1->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM1->CCMR1 |= (0x6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

