 */
void SystemClock_Config_150MHz_Range1Normal(void)
{
    /* 1. Enable PWR peripheral clock */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* 2. Set voltage regulator to Range 1 normal mode (max 150 MHz) */
    PWR->CR5 |= PWR_CR5_R1MODE;

    /* 3. Configure Flash read access latency: 4 WS for 150 MHz in Range 1 normal mode */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS) {
        /* Wait for Flash latency update */
    }

    /* 4. Configure PLL:
     *    Source: HSI16 (16 MHz)
     *    M = 4  -> 16 MHz / 4 = 4 MHz VCO input
     *    N = 75 -> 4 MHz * 75 VCO output
     *    R = 2  -> (4 MHz * 75) / 2 = 150 MHz PLLCLK
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_1 |
                   ((4 - 1) << RCC_PLLCFGR_PLLM_Pos) |
                   (75 << RCC_PLLCFGR_PLLN_Pos) |
