    RCC->AHB2ENR  |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOCEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* 3. Configure PA8 (I2C3_SCL, AF2) as Alternate Function, Open-Drain, High-Speed */
    GPIOA->MODER   = (GPIOA->MODER & ~GPIO_MODER_MODE8) | (2UL << GPIO_MODER_MODE8_Pos);
    GPIOA->OTYPER |= GPIO_OTYPER_OT8;
    GPIOA->OSPEEDR |= (3UL << GPIO_OSPEEDR_OSPEED8_Pos);
    GPIOA->AFR[1]  = (GPIOA->AFR[1] & ~(0xFUL << ((8 - 8) * 4))) | (2UL << ((8 - 8) * 4));

    /* 4. Configure PC9 (I2C3_SDA, AF8) as Alternate Function, Open-Drain, High-Speed */
    GPIOC->MODER   = (GPIOC->MODER & ~GPIO_MODER_MODE9) | (2UL << GPIO_MODER_MODE9_Pos);
    GPIOC->OTYPER |= GPIO_OTYPER_OT9;
    GPIOC->OSPEEDR |= (3UL << GPIO_OSPEEDR_OSPEED9_Pos);
    GPIOC->AFR[1]  = (GPIOC->AFR[1] & ~(0xFUL << ((9 - 8) * 4))) | (8UL << ((9 - 8) * 4));

    /* 5. Ensure I2C3 is disabled (PE = 0) before modifying TIMINGR (RM0440 §39.4.5) */
    I2C3->CR1 &= ~I2C_CR1_PE;

