     * 3. TIM1 Configuration: 20 kHz PWM, 25 % Duty Cycle on Channel 1
     * ------------------------------------------------------------------------ */

    /* Timer clock = 170 MHz (APB2 prescaler = 1 -> TIM1CLK = 170 MHz)
     * Desired PWM frequency = 20,000 Hz:
     *   ARR = (TIM1CLK / ((PSC + 1) * f_target)) - 1
     *   With PSC = 0: ARR = (170,000,000 / (1 * 20,000)) - 1 = 8499
     * Duty cycle = 25 %:
     *   CCR1 = (ARR + 1) * 25% = 8500 * 0.25 = 2125
     */
    TIM1->PSC  = 0U;
    TIM1->ARR  = 8499U;
    TIM1->CCR1 = 2125U;

    /* Configure Channel 1:
     * - Output compare mode: PWM mode 1 (OC1M = 0110b)
     * - Enable preload register for CCR1 (OC1PE = 1)
     */
    TIM1->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM1->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Configure Channel 1 output polarity and enable:
     * - Active-high polarity: CC1P = 0
     * - Enable channel 1 output: CC1E = 1
     */
    TIM1->CCER &= ~TIM_CCER_CC1P;
    TIM1->CCER |= TIM_CCER_CC1E;

    /* Enable ARR preload register buffer (ARPE = 1) */
    TIM1->CR1 |= TIM_CR1_ARPE;

    /* Generate an update event to load preloaded registers into shadow registers */
    TIM1->EGR |= TIM_EGR_UG;

    /* TIM1 is an advanced timer: Main Output Enable (MOE) must be set in BDTR */
    TIM1->BDTR |= TIM_BDTR_MOE;

    /* Enable counter */
    TIM1->CR1 |= TIM_CR1_CEN;

    /* Loop forever; PWM generation continues autonomously in hardware */
    while (1) {
    }
}
