/**
 * @brief Initialize PA6 (TIM3_CH1, 20 kHz, 40% duty) and PA7 (TIM17_CH1, 1 kHz, 50% duty).
 *        Clock: SYSCLK = PCLK1 = PCLK2 = 170 MHz.
 */
void init_pwm_outputs(void)
{
    /* -------------------------------------------------------------
     * 1. Enable GPIOA Peripheral Clock
     * ------------------------------------------------------------- */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;

    /* -------------------------------------------------------------
     * 2. Configure PA6 (AF2 -> TIM3_CH1) for 20 kHz LED PWM
     * ------------------------------------------------------------- */
    GPIOA->MODER &= ~GPIO_MODER_MODE6_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE6_Pos);          /* AF mode */
    GPIOA->OSPEEDR |= (2U << GPIO_OSPEEDR_OSPEED6_Pos);     /* High speed */

    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL6_Msk;
    GPIOA->AFR[0] |= (2U << GPIO_AFRL_AFSEL6_Pos);          /* AF2 = TIM3_CH1 */

    /* Enable TIM3 clock on APB1 */
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN;

    TIM3->PSC = 0U;                                         /* 170 MHz count clock */
    TIM3->ARR = 8499U;                                      /* 170 MHz / 8500 = 20 kHz */
    TIM3->CCR1 = 3400U;                                     /* 40% duty cycle */

    /* PWM Mode 1 with preload enabled on Channel 1 */
    TIM3->CCMR1 &= ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk);
    TIM3->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Channel 1 output enable, active-high */
    TIM3->CCER &= ~TIM_CCER_CC1P;
    TIM3->CCER |= TIM_CCER_CC1E;

    /* Start TIM3 with auto-reload preload enabled */
    TIM3->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;
    TIM3->EGR |= TIM_EGR_UG;

    /* -------------------------------------------------------------
     * 3. Configure PA7 (AF1 -> TIM17_CH1) for 1 kHz Buzzer PWM
     * ------------------------------------------------------------- */
    GPIOA->MODER &= ~GPIO_MODER_MODE7_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE7_Pos);          /* AF mode */
    GPIOA->OSPEEDR |= (2U << GPIO_OSPEEDR_OSPEED7_Pos);     /* High speed */

    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL7_Msk;
    GPIOA->AFR[0] |= (1U << GPIO_AFRL_AFSEL7_Pos);          /* AF1 = TIM17_CH1 */

    /* Enable TIM17 clock on APB2 */
    RCC->APB2ENR |= RCC_APB2ENR_TIM17EN;

    TIM17->PSC = 3U;                                        /* 170 MHz / 4 = 42.5 MHz */
    TIM17->ARR = 42499U;                                    /* 42.5 MHz / 42500 = 1 kHz */
    TIM17->CCR1 = 21250U;                                   /* 50% duty cycle */

    /* PWM Mode 1 with preload enabled on Channel 1 */
    TIM17->CCMR1 &= ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk);
    TIM17->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Channel 1 output enable, active-high */
    TIM17->CCER &= ~TIM_CCER_CC1P;
    TIM17->CCER |= TIM_CCER_CC1E;

    /* Enable Main Output (MOE) required for TIM17 */
    TIM17->BDTR |= TIM_BDTR_MOE;

    /* Start TIM17 with auto-reload preload enabled */
    TIM17->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;
    TIM17->EGR |= TIM_EGR_UG;
