```c
#include "stm32g4xx.h"

/**
 * @brief Initialize USART3 on PB10 (TX) and PB11 (RX) at 115200 8N1.
 *        Clock: PCLK1 = 170 MHz, oversampling by 16.
 */
void usart3_debug_init(void)
{
    /* 1. Enable GPIOB and USART3 peripheral clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOBEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART3EN;

    /* 2. Configure PB10 (TX) and PB11 (RX) as Alternate Function (MODER = 10b) */
    GPIOB->MODER &= ~(GPIO_MODER_MODE10_Msk | GPIO_MODER_MODE11_Msk);
    GPIOB->MODER |= (2U << GPIO_MODER_MODE10_Pos) | (2U << GPIO_MODER_MODE11_Pos);

    /* High speed output on PB10 (TX) */
    GPIOB->OSPEEDR |= (2U << GPIO_OSPEEDR_OSPEED10_Pos);

    /* Enable pull-up on PB11 (RX) to hold line high when idle/floating */
    GPIOB->PUPDR &= ~GPIO_PUPDR_PUPD11_Msk;
    GPIOB->PUPDR |= (1U << GPIO_PUPDR_PUPD11_Pos);

    /* 3. Assign PB10 and PB11 to AF7 (USART3_TX and USART3_RX) in AFRH */
    GPIOB->AFR[1] &= ~(GPIO_AFRH_AFSEL10_Msk | GPIO_AFRH_AFSEL11_Msk);
    GPIOB->AFR[1] |= (7U << GPIO_AFRH_AFSEL10_Pos) | (7U << GPIO_AFRH_AFSEL11_Pos);

    /* 4. Configure Baud Rate:
     *    BRR = f_CK / Baud = 170,000,000 / 115,200 = 1476 (0x05C4)
     *    Written before enabling the USART (UE).
     */
    USART3->BRR = 1476U;

    /* 5. Configure Frame Format:
     *    - 1 Stop bit: STOP[1:0] = 00b in CR2 (default after reset)
     *    USART3->CR2 &= ~USART_CR2_STOP_Msk;
     */

    /* 6. Configure CR1 and enable USART3:
     *    - Word length: 8 data bits (M0 = 0, M1 = 0)
     *    - Parity: disabled (PCE = 0)
     *    - Oversampling: by 16 (OVER8 = 0)
     *    - Transmitter enable: TE = 1
     *    - Receiver enable: RE = 1
     *    - Peripheral enable: UE = 1
     */
    USART3->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;
}

/**
 * @brief Transmit a single character over USART3 (polling).
 */
void usart3_write_char(char c)
{
    /* Wait until the transmit data register is empty (TXE / TXFNF) */
    while (!(USART3->ISR & USART_ISR_TXE_TXFNF)) {
        /* Busy wait */
    }
    USART3->TDR = (uint8_t)c;
}

/**
 * @brief Receive a single character from USART3 (polling).
 */
char usart3_read_char(void)
{
    /* Wait until character is received into RDR (RXNE / RXFNE) */
    while (!(USART3->ISR & USART_ISR_RXNE_RXFNE)) {
        /* Busy wait */
    }
    return (char)(USART3->RDR & 0xFFU);
}
