#### 2. Bare-Metal CMSIS Implementation (`system_clock_config.c`)

```c
#include "stm32g4xx.h"

/**
 * @brief  Configures the system clock to 170 MHz on an STM32G474 (VDD = 3.6 V).
 *         Uses the internal 16 MHz HSI oscillator and the main PLL.
 */
void SystemClock_Config(void)
{
    /* 1. Enable power interface clock to access PWR registers */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;
    (void)RCC->APB1ENR1; // Read-after-write delay to guarantee clock enable

    /* 2. Configure Main Regulator in Range 1 Boost Mode (SYSCLK > 150 MHz up to 170 MHz)
     * Clear R1MODE (bit 8) in PWR_CR5 to select Boost Mode [STM32G474_RM0440 p.232, p.267]
     */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* 3. Configure Flash latency:
     * 4 wait states (5 CPU cycles) required for 170 MHz in Range 1 Boost Mode [STM32G474_RM0440 p.98]
     * Enable prefetch, instruction cache, and data cache [STM32G474_RM0440 p.130]
     */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY_Msk) | FLASH_ACR_LATENCY_4WS;
    FLASH->ACR |= FLASH_ACR_PRFTEN | FLASH_ACR_ICEN | FLASH_ACR_DCEN;
    while ((FLASH->ACR & FLASH_ACR_LATENCY_Msk) != FLASH_ACR_LATENCY_4WS);

    /* 4. Ensure HSI16 is ON and stable */
    RCC->CR |= RCC_CR_HSION;
    while (!(RCC->CR & RCC_CR_HSIRDY));

    /* 5. Configure Main PLL:
     *    Source: HSI16 (16 MHz)
     *    M = /4 (field value 3)  => PLL_IN = 4 MHz [STM32G474_Datasheet p.123]
     *    N = *85 (field value 85) => VCO = 340 MHz [STM32G474_Datasheet p.123]
     *    R = /2 (field value 0)  => PLL_R = 170 MHz [STM32G474_Datasheet p.123]
     */
    RCC->CR &= ~RCC_CR_PLLON;
    while (RCC->CR & RCC_CR_PLLRDY); // Wait until PLL is disabled before reconfiguring

    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSI |
                   (3U << RCC_PLLCFGR_PLLM_Pos) |
                   (85U << RCC_PLLCFGR_PLLN_Pos) |
                   (0U << RCC_PLLCFGR_PLLR_Pos) |
                   RCC_PLLCFGR_PLLREN;

    /* Enable PLL and wait for lock */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    /* 6. Switch system clock to PLL:
     * As recommended in RM0440, set intermediate AHB prescaler division (/2) before
     * switching to the higher frequency PLL clock, switch SYSCLK, then restore /1 [STM32G474_RM0440 p.232].
     */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE_Msk) | RCC_CFGR_HPRE_DIV2;

    /* Select PLL as SYSCLK source */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW_Msk) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS_Msk) != RCC_CFGR_SWS_PLL);

    /* Brief wait to let internal clock domain stabilize */
    for (volatile int i = 0; i < 200; i++);

    /* Restore AHB prescaler to /1 (HCLK = 170 MHz) */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_HPRE_Msk) | RCC_CFGR_HPRE_DIV1;
}
