    /* Prescaler: 170 MHz / (3 + 1) = 42.5 MHz counter clock */
    TIM3->PSC = 3U;

    /* Auto-reload: 42.5 MHz / (42499 + 1) = 1000 Hz PWM period */
    TIM3->ARR = 42499U;

    /* 50% duty cycle: CCR1 = 42500 / 2 = 21250 */
    TIM3->CCR1 = 21250U;

    /* 4. Configure Channel 1 for PWM Mode 1 with preload enabled */
    /* OC1M[3:0] = 0b0110 (PWM mode 1), OC1PE = 1 (preload enable), CC1S = 0b00 (output) */
