    /* Enable ARPE, update shadow registers, and start counter */
    TIM3->CR1 |= TIM_CR1_ARPE;
    TIM3->EGR = TIM_EGR_UG;
    TIM3->CR1 |= TIM_CR1_CEN;

    /* ---------------------------------------------------------------------- */
    /* 4. Configure TIM17 (PA7, 1 kHz, 50 % Duty Cycle)                       */
    /* ---------------------------------------------------------------------- */
    /* f_tim = 170 MHz; f_pwm = 1 kHz -> PSC = 3 (div 4), ARR = 42499, CCR1 = 21250 */
    TIM17->PSC = 3U;
    TIM17->ARR = 42499U;
    TIM17->CCR1 = 21250U;

    /* PWM Mode 1 with preload enabled on Channel 1 */
    TIM17->CCMR1 &= ~TIM_CCMR1_OC1M_Msk;
    TIM17->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* Output enable, active-high polarity */
    TIM17->CCER &= ~TIM_CCER_CC1P;
    TIM17->CCER |= TIM_CCER_CC1E;

    /* Advanced timer break/dead-time: assert Main Output Enable (MOE) */
    TIM17->BDTR |= TIM_BDTR_MOE;

    /* Enable ARPE, update shadow registers, and start counter */
    TIM17->CR1 |= TIM_CR1_ARPE;
    TIM17->EGR = TIM_EGR_UG;
    TIM17->CR1 |= TIM_CR1_CEN;

    /* ---------------------------------------------------------------------- */
    /* 5. Configure USART3 (PB10 TX, PB11 RX, 115200 Baud, 8N1, OVER16)      */
    /* ---------------------------------------------------------------------- */
    /* Ensure USART3 is disabled prior to setting BRR and control registers   */
    USART3->CR1 = 0U;
    USART3->CR2 = 0U;
    USART3->CR3 = 0U;

    /*
     * Baud Rate calculation:
     * USART3 kernel clock = PCLK1 = 170 MHz (RCC_CCIPR default USART3SEL = 00b)
     * OVER8 = 0 (oversampling by 16)
     * BRR = round(170,000,000 / 115,200) = round(1475.694) = 1476 (0x05C4)
     * Realized baud rate = 115,176.15 baud (-0.02 % error)
     */
    USART3->BRR = 1476U;

    /* Enable USART3, Transmitter, and Receiver */
    USART3->CR1 |= (USART_CR1_UE | USART_CR1_TE | USART_CR1_RE);

    /* ---------------------------------------------------------------------- */
    /* Main loop                                                              */
    /* ---------------------------------------------------------------------- */
    while (1)
    {
    }
}
