     * 2. GPIO Configuration: PA6 (TIM3_CH1, AF2) and PA7 (TIM17_CH1, AF1)
     * ========================================================================= */
    /* Alternate Function mode (10b) for PA6 and PA7 */
    GPIOA->MODER &= ~(GPIO_MODER_MODE6_Msk | GPIO_MODER_MODE7_Msk);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE6_Pos) | (2U << GPIO_MODER_MODE7_Pos);

    /* Output type: Push-Pull (0) */
    GPIOA->OTYPER &= ~(GPIO_OTYPER_OT6 | GPIO_OTYPER_OT7);

    /* Output speed: Very High Speed (11b) */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED6_Pos) | (3U << GPIO_OSPEEDR_OSPEED7_Pos);

    /* No pull-up, no pull-down (00b) */
    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD6_Msk | GPIO_PUPDR_PUPD7_Msk);

    /* Alternate function selection: PA6 -> AF2, PA7 -> AF1 */
    GPIOA->AFR[0] &= ~((0xFU << GPIO_AFRL_AFSEL6_Pos) | (0xFU << GPIO_AFRL_AFSEL7_Pos));
    GPIOA->AFR[0] |= (2U << GPIO_AFRL_AFSEL6_Pos) | (1U << GPIO_AFRL_AFSEL7_Pos);

    /* =========================================================================
     * 3. GPIO Configuration: PB10 (USART3_TX, AF7) and PB11 (USART3_RX, AF7)
     * ========================================================================= */
    /* Alternate Function mode (10b) for PB10 and PB11 */
    GPIOB->MODER &= ~(GPIO_MODER_MODE10_Msk | GPIO_MODER_MODE11_Msk);
    GPIOB->MODER |= (2U << GPIO_MODER_MODE10_Pos) | (2U << GPIO_MODER_MODE11_Pos);

    /* Output type: Push-Pull (0) */
    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT10 | GPIO_OTYPER_OT11);

    /* Output speed: Very High Speed (11b) */
    GPIOB->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED10_Pos) | (3U << GPIO_OSPEEDR_OSPEED11_Pos);

    /* Pull-up on RX (PB11) to avoid floating line; no pull on TX (PB10) */
