    GPIOB->PUPDR |= (1U << GPIO_PUPDR_PUPD11_Pos);

    /* Alternate function selection: PB10 -> AF7, PB11 -> AF7 in AFRH (AFR[1]) */
    GPIOB->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL10_Pos) | (0xFU << GPIO_AFRH_AFSEL11_Pos));
    GPIOB->AFR[1] |= (7U << GPIO_AFRH_AFSEL10_Pos) | (7U << GPIO_AFRH_AFSEL11_Pos);

    /* =========================================================================
     * 4. Configure TIM3 for PA6 (20 kHz, 40% Duty Cycle)
     * ========================================================================= */
    TIM3->PSC = 0;              /* Counter clock = 170 MHz */
    TIM3->ARR = 8499;           /* Frequency = 170 MHz / 8500 = 20 kHz */
    TIM3->CCR1 = 3400;          /* Duty cycle = 3400 / 8500 = 40% */

    /* Channel 1: PWM Mode 1 (OC1M = 0110b), enable preload (OC1PE) */
