    USART3->CR1 = 0;
    USART3->CR2 = 0; /* 1 stop bit (STOP[1:0] = 00b) */
    USART3->CR3 = 0;

    /* Write BRR before enabling USART:
     * USARTDIV = 170000000 / 115200 = 1475.694 -> BRR = 1476
