/**
 * @brief Send a single character over USART3 (polling).
 */
void usart3_write_char(char c)
{
    while (!(USART3->ISR & USART_ISR_TXE_TXFNF))
    {
        /* Wait until transmit register is ready */
    }
    USART3->TDR = (uint8_t)c;
}

/**
 * @brief Receive a single character from USART3 (polling).
 */
char usart3_read_char(void)
{
    while (!(USART3->ISR & USART_ISR_RXNE_RXFNE))
    {
        /* Wait until character is received */
    }
    return (char)(USART3->RDR & 0xFF);
}
