/**
 * @brief Trigger a single conversion and return the raw ADC code
 */
int16_t saadc_read_raw_blocking(void) {
    // Start SAADC and arm EasyDMA buffer
    NRF_SAADC->EVENTS_STARTED = 0;
    NRF_SAADC->TASKS_START = 1;
    while (!NRF_SAADC->EVENTS_STARTED);

    // Trigger one sample acquisition and conversion
    NRF_SAADC->EVENTS_END = 0;
    NRF_SAADC->TASKS_SAMPLE = 1;
    while (!NRF_SAADC->EVENTS_END);

    // Stop SAADC
    NRF_SAADC->EVENTS_STOPPED = 0;
    NRF_SAADC->TASKS_STOP = 1;
    while (!NRF_SAADC->EVENTS_STOPPED);

    // Clamp negative values due to slight zero offset
    if (saadc_sample_buffer[0] < 0) {
        return 0;
    }
    return saadc_sample_buffer[0];
}

/**
 * @brief Read 5 V sensor voltage via the 1:1 resistor divider
 * @return Sensor input voltage in Volts
 */
float read_5v_sensor_voltage(void) {
    int16_t raw = saadc_read_raw_blocking();

    // V_AIN0 = raw * (0.6 V / (1/6)) / 4096 = raw * 3.6 V / 4096
    // V_sensor = V_AIN0 * (R1 + R2) / R2 = V_AIN0 * 2.0
    float v_pin = ((float)raw * 3.6f) / 4096.0f;
    float v_sensor = v_pin * 2.0f;
    return v_sensor;
}
