### Bare-Metal CMSIS C Code

```c
#include "stm32g4xx.h"

void tim3_ch1_pwm_init(void) {
    /* 1. Enable GPIOA and TIM3 peripheral clock gates */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;
    RCC->APB1ENR1 |= RCC_APB1ENR1_TIM3EN;

    /* 2. Configure PA6 in Alternate Function mode (MODER6 = 10b) */
    GPIOA->MODER &= ~GPIO_MODER_MODE6_Msk;
    GPIOA->MODER |= (2U << GPIO_MODER_MODE6_Pos);

    /* 3. Configure PA6 alternate function to AF2 (TIM3_CH1) in AFRL */
    GPIOA->AFR[0] &= ~(0xFU << GPIO_AFRL_AFSEL6_Pos);
    GPIOA->AFR[0] |= (2U << GPIO_AFRL_AFSEL6_Pos);

    /* 4. Configure time base for 1 kHz PWM (f_TIM3CLK = 170 MHz):
     *    f_PWM = 170 MHz / ((PSC + 1) * (ARR + 1)) = 170 MHz / (4 * 42500) = 1 kHz
     */
    TIM3->PSC = 3U;
    TIM3->ARR = 42499U;

    /* 5. Set 50 % duty cycle: CCR1 = 42500 * 50% = 21250 */
    TIM3->CCR1 = 21250U;

    /* 6. Channel 1 configuration:
     *    - CC1S = 00b (Output)
     *    - OC1M = 0110b (PWM mode 1)
     *    - OC1PE = 1 (Output compare 1 preload enable)
     */
    TIM3->CCMR1 &= ~(TIM_CCMR1_OC1M_Msk | TIM_CCMR1_CC1S_Msk);
    TIM3->CCMR1 |= (6U << TIM_CCMR1_OC1M_Pos) | TIM_CCMR1_OC1PE;

    /* 7. Output polarity active-high (CC1P = 0) and enable output (CC1E = 1) */
    TIM3->CCER &= ~TIM_CCER_CC1P;
    TIM3->CCER |= TIM_CCER_CC1E;

    /* 8. Generate an update event to load preloaded PSC, ARR, and CCR1 values */
    TIM3->EGR = TIM_EGR_UG;

    /* 9. Enable Auto-reload preload (ARPE) and start counter (CEN) */
    TIM3->CR1 |= TIM_CR1_ARPE | TIM_CR1_CEN;
}
