### Bare-Metal C Code

```c
#include "stm32g4xx.h"

int main(void)
{
    /* -------------------------------------------------------------------------
     * 1. POWER & CLOCK CONFIGURATION (170 MHz via HSE 16 MHz)
     * ------------------------------------------------------------------------- */
    /* Enable PWREN */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* Set Flash Latency to 4 Wait States (WS) for 170 MHz at Range 1 Boost */
    FLASH->ACR &= ~FLASH_ACR_LATENCY;
    FLASH->ACR |= FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS);

    /* Switch to Range 1 Boost Mode: clear R1MODE bit in PWR_CR5 */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* Start HSE (16 MHz) */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY));

    /* Configure PLL:
     * Source = HSE (16 MHz)
     * M = 4  (bits: 0011 -> /4)
     * N = 85 (value 85)
     * R = 2  (bits: 00 -> /2)
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE
                 | ((4 - 1) << RCC_PLLCFGR_PLLM_Pos)
                 | (85 << RCC_PLLCFGR_PLLN_Pos)
                 | (0 << RCC_PLLCFGR_PLLR_Pos)
                 | RCC_PLLCFGR_PLLREN;

    /* Enable PLL and wait for lock */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    /* Select PLL as system clock */
    RCC->CFGR &= ~RCC_CFGR_SW;
    RCC->CFGR |= RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);

    /* -------------------------------------------------------------------------
     * 2. GPIO CLOCKS & PIN ALLOCATION
     * ------------------------------------------------------------------------- */
    /* Enable GPIOA and GPIOB clocks */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOBEN;

    /* USART2 Pins: PA2 (TX) and PA3 (RX) -> AF7 */
    GPIOA->MODER &= ~(GPIO_MODER_MODE2 | GPIO_MODER_MODE3);
    GPIOA->MODER |= (2 << GPIO_MODER_MODE2_Pos) | (2 << GPIO_MODER_MODE3_Pos);
    GPIOA->AFR[0] |= (7 << GPIO_AFRL_AFSEL2_Pos) | (7 << GPIO_AFRL_AFSEL3_Pos);
    GPIOA->OSPEEDR |= (3 << GPIO_OSPEEDR_OSPEED2_Pos) | (3 << GPIO_OSPEEDR_OSPEED3_Pos);

    /* I2C1 Pins: PB8 (SCL) and PB9 (SDA) -> AF4, Open-Drain */
    GPIOB->MODER &= ~(GPIO_MODER_MODE8 | GPIO_MODER_MODE9);
    GPIOB->MODER |= (2 << GPIO_MODER_MODE8_Pos) | (2 << GPIO_MODER_MODE9_Pos);
    GPIOB->OTYPER |= GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9;
    GPIOB->AFR[1] |= (4 << GPIO_AFRH_AFSEL8_Pos) | (4 << GPIO_AFRH_AFSEL9_Pos);

    /* -------------------------------------------------------------------------
     * 3. USART2 INITIALIZATION (115200 bps, 8N1, 16x oversampling)
     * ------------------------------------------------------------------------- */
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART2EN;

    /* PCLK1 = 170 MHz. USARTDIV = 170000000 / 115200 = 1476 (0x05C4) */
    USART2->BRR = 1476;
    USART2->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

    /* -------------------------------------------------------------------------
     * 4. I2C1 INITIALIZATION (100 kHz Standard Mode, Controller)
     * ------------------------------------------------------------------------- */
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C1EN;

    /* Disable I2C1 prior to configuration */
    I2C1->CR1 &= ~I2C_CR1_PE;

    /* Timing register for 100 kHz from 170 MHz clock:
     * PRESC = 15 (div by 16)
     * SCLDEL = 4, SDADEL = 2, SCLH = 43 (0x2B), SCLL = 53 (0x35)
     */
    I2C1->TIMINGR = (15 << I2C_TIMINGR_PRESC_Pos)
                  | (4  << I2C_TIMINGR_SCLDEL_Pos)
                  | (2  << I2C_TIMINGR_SDADEL_Pos)
                  | (43 << I2C_TIMINGR_SCLH_Pos)
                  | (53 << I2C_TIMINGR_SCLL_Pos);

    I2C1->CR1 |= I2C_CR1_PE;

    /* -------------------------------------------------------------------------
     * 5. MAIN LOOP
     * ------------------------------------------------------------------------- */
    while (1)
    {
        /* Ready for sensor acquisition and UART forwarding */
    }
}
