    GPIOB->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);

    /* High speed */
    GPIOB->OSPEEDR |= (2U << GPIO_OSPEEDR_OSPEED8_Pos) | (2U << GPIO_OSPEEDR_OSPEED9_Pos);

    /* No internal pull-ups (board provides 4.7 kOhm external pull-ups) */
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD8_Msk | GPIO_PUPDR_PUPD9_Msk);

