    I2C1->TIMINGR = (16U << I2C_TIMINGR_PRESC_Pos)
                  | (4U  << I2C_TIMINGR_SCLDEL_Pos)
                  | (2U  << I2C_TIMINGR_SDADEL_Pos)
                  | (46U << I2C_TIMINGR_SCLH_Pos)
                  | (49U << I2C_TIMINGR_SCLL_Pos);

    /* Enable I2C1 */
    I2C1->CR1 |= I2C_CR1_PE;

    /* Main loop */
    while (1)
    {
        /* Ready for sensor acquisition via I2C1 and transfer via USART2 */
    }
}
