    I2C1->TIMINGR = (15U << I2C_TIMINGR_PRESC_Pos)
                  | (4U  << I2C_TIMINGR_SCLDEL_Pos)
                  | (2U  << I2C_TIMINGR_SDADEL_Pos)
                  | (51U << I2C_TIMINGR_SCLH_Pos)
                  | (52U << I2C_TIMINGR_SCLL_Pos);

    /* Enable I2C1 peripheral */
    I2C1->CR1 |= I2C_CR1_PE;

    /* -------------------------------------------------------------------------
     * 5. MAIN LOOP
     * ---------------------------------------------------------------------- */
    while (1)
    {
        /* Ready for sensor acquisition and UART forwarding */
    }
