    GPIOA->MODER |= (2U << GPIO_MODER_MODE3_Pos);
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL3_Msk;
    GPIOA->AFR[0] |= (7U << GPIO_AFRL_AFSEL3_Pos);

    /* I2C1 Pins: PB8 (SCL) and PB9 (SDA) -> AF4, Open-Drain, High Speed */
    /* PB8 */
    GPIOB->MODER &= ~GPIO_MODER_MODE8_Msk;
    GPIOB->MODER |= (2U << GPIO_MODER_MODE8_Pos);
    GPIOB->OTYPER |= GPIO_OTYPER_OT8;
    GPIOB->AFR[1] &= ~GPIO_AFRH_AFSEL8_Msk;
    GPIOB->AFR[1] |= (4U << GPIO_AFRH_AFSEL8_Pos);
    GPIOB->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED8_Pos);

