    GPIOB->MODER |= (2U << GPIO_MODER_MODE9_Pos);
    GPIOB->OTYPER |= GPIO_OTYPER_OT9;
    GPIOB->AFR[1] &= ~GPIO_AFRH_AFSEL9_Msk;
    GPIOB->AFR[1] |= (4U << GPIO_AFRH_AFSEL9_Pos);
    GPIOB->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED9_Pos);

    /* ------------------------------------------------------------------------
     * 3. USART2 CONFIGURATION (921600 bps, 8N1, Oversampling /16)
     * ------------------------------------------------------------------------ */
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART2EN;

    /* BRR = 170,000,000 / 921,600 = 184 (0xB8) */
    USART2->BRR = 184U;

    /* 8 data bits, no parity (M[1:0] = 00, PCE = 0), 1 stop bit (STOP[1:0] = 00) */
    USART2->CR1 = USART_CR1_TE | USART_CR1_RE;
