    /* Enable Power Controller clock */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* Switch to Range 1 Boost Mode: clear R1MODE (bit 0) in PWR_CR5 */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* Configure Flash Latency: 4 wait states required at 170 MHz */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS);

    /* Enable HSE oscillator */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY));

    /* Configure Main PLL:
     * Source = HSE (8 MHz)
     * M = 2 (PLLM = 0001b -> /2 => VCO_IN = 4 MHz)
     * N = 85 (PLLN = 85 => VCO_OUT = 340 MHz)
     * R = 2 (PLLR = 00b -> /2 => PLLCLK = 170 MHz)
     * Enable PLLR output
     */
    RCC->PLLCFGR = RCC_PLLCFGR_PLLSRC_HSE
                 | (1U << RCC_PLLCFGR_PLLM_Pos)
                 | (85U << RCC_PLLCFGR_PLLN_Pos)
                 | RCC_PLLCFGR_PLLREN;

    /* Enable PLL and wait for lock */
    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY));

    /* Set AHB and APB prescalers to 1 (reset defaults) */
    RCC->CFGR &= ~(RCC_CFGR_HPRE | RCC_CFGR_PPRE1 | RCC_CFGR_PPRE2);

    /* Switch SYSCLK to PLL */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL);

    /* -------------------------------------------------------------------------
     * 2. GPIO Port Clocks
     * ------------------------------------------------------------------------- */
    RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOBEN;

    /* -------------------------------------------------------------------------
     * 3. USART2 Pin Allocation & Peripheral Setup
     *    PA2 -> USART2_TX (AF7, Push-Pull, High Speed)
     *    PA3 -> USART2_RX (AF7, Floating Input)
     * ------------------------------------------------------------------------- */
    /* Set PA2, PA3 to Alternate Function mode (10b) */
    GPIOA->MODER &= ~(GPIO_MODER_MODE2 | GPIO_MODER_MODE3);
    GPIOA->MODER |= (2U << GPIO_MODER_MODE2_Pos) | (2U << GPIO_MODER_MODE3_Pos);

    /* Set AF7 (0111b) for PA2 and PA3 in AFRL */
    GPIOA->AFR[0] &= ~((0xFU << GPIO_AFRL_AFSEL2_Pos) | (0xFU << GPIO_AFRL_AFSEL3_Pos));
    GPIOA->AFR[0] |= (7U << GPIO_AFRL_AFSEL2_Pos) | (7U << GPIO_AFRL_AFSEL3_Pos);

    /* Set high speed for PA2 (TX) */
    GPIOA->OSPEEDR |= (3U << GPIO_OSPEEDR_OSPEED2_Pos);

    /* Enable USART2 clock (PCLK1 = 170 MHz by default) */
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART2EN;

    /* Baud Rate = 115200: BRR = 170000000 / 115200 = 1476 */
    USART2->BRR = 1476U;

    /* Enable Transmitter, Receiver, and USART2 peripheral (8N1, oversample 16) */
    USART2->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

    /* -------------------------------------------------------------------------
     * 4. I2C1 Pin Allocation & Peripheral Setup
     *    PB8 -> I2C1_SCL (AF4, Open-Drain)
     *    PB9 -> I2C1_SDA (AF4, Open-Drain)
     * ------------------------------------------------------------------------- */
    /* Set PB8, PB9 to Alternate Function mode (10b) */
    GPIOB->MODER &= ~(GPIO_MODER_MODE8 | GPIO_MODER_MODE9);
    GPIOB->MODER |= (2U << GPIO_MODER_MODE8_Pos) | (2U << GPIO_MODER_MODE9_Pos);

    /* Configure PB8 and PB9 as Open-Drain */
    GPIOB->OTYPER |= GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9;

    /* Disable internal pull-up/pull-down (module has 4.7 kOhm external pull-ups) */
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD8 | GPIO_PUPDR_PUPD9);

    /* Set AF4 (0100b) for PB8 and PB9 in AFRH */
    GPIOB->AFR[1] &= ~((0xFU << GPIO_AFRH_AFSEL8_Pos) | (0xFU << GPIO_AFRH_AFSEL9_Pos));
    GPIOB->AFR[1] |= (4U << GPIO_AFRH_AFSEL8_Pos) | (4U << GPIO_AFRH_AFSEL9_Pos);

    /* Enable I2C1 clock (PCLK1 = 170 MHz) */
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C1EN;

    /* Ensure I2C1 is disabled before programming TIMINGR */
    I2C1->CR1 &= ~I2C_CR1_PE;

    /* TIMINGR: PRESC=15, SCLDEL=4, SDADEL=2, SCLH=51, SCLL=53 (100 kHz at 170 MHz) */
    I2C1->TIMINGR = 0xF0423335U;

    /* Enable I2C1 peripheral */
    I2C1->CR1 |= I2C_CR1_PE;

    /* -------------------------------------------------------------------------
     * 5. Main Loop
     * ------------------------------------------------------------------------- */
    while (1)
    {
        /* Ready to execute non-blocking or polled acquisition & forwarding */
    }
}
