### Bare-Metal C Implementation

```c
#include "stm32g4xx.h"

int main(void)
{
    /* -------------------------------------------------------------------------
     * 1. Power & Flash Configuration for 170 MHz Range 1 Boost Mode
     * ------------------------------------------------------------------------- */
    RCC->APB1ENR1 |= RCC_APB1ENR1_PWREN;

    /* Enter Range 1 Boost Mode (R1MODE bit 0 = 0 in PWR_CR5) */
    PWR->CR5 &= ~PWR_CR5_R1MODE;

    /* Set Flash Latency to 4 Wait States (required for 170 MHz in Range 1 Boost) */
    FLASH->ACR = (FLASH->ACR & ~FLASH_ACR_LATENCY) | FLASH_ACR_LATENCY_4WS;
    while ((FLASH->ACR & FLASH_ACR_LATENCY) != FLASH_ACR_LATENCY_4WS) {
        /* Wait for Flash latency to apply */
    }

    /* -------------------------------------------------------------------------
     * 2. HSE and Main PLL (170 MHz SYSCLK)
     * ------------------------------------------------------------------------- */
    /* Enable HSE bypass/crystal oscillator */
    RCC->CR |= RCC_CR_HSEON;
    while (!(RCC->CR & RCC_CR_HSERDY)) {
        /* Wait for HSE to stabilize */
    }

    /* Configure PLL:
     * PLLSRC = HSE (3)
     * PLLM   = 4 (value = 3: (3 + 1) = 4) -> 16 MHz / 4 = 4 MHz
     * PLLN   = 85 (value = 85)            -> 4 MHz * 85 = 340 MHz VCO
     * PLLR   = 2 (value = 0: (0b00 + 1) * 2 / wait, bit 26:25: 00 = /2) -> 340 / 2 = 170 MHz
     * Enable PLLR output
     */
    RCC->PLLCFGR = (3UL << RCC_PLLCFGR_PLLSRC_Pos)
                 | (3UL << RCC_PLLCFGR_PLLM_Pos)
                 | (85UL << RCC_PLLCFGR_PLLN_Pos)
                 | (0UL << RCC_PLLCFGR_PLLR_Pos)
                 | RCC_PLLCFGR_PLLREN;

    RCC->CR |= RCC_CR_PLLON;
    while (!(RCC->CR & RCC_CR_PLLRDY)) {
        /* Wait for PLL lock */
    }

    /* Switch SYSCLK to Main PLL */
    RCC->CFGR = (RCC->CFGR & ~RCC_CFGR_SW) | RCC_CFGR_SW_PLL;
    while ((RCC->CFGR & RCC_CFGR_SWS) != RCC_CFGR_SWS_PLL) {
        /* Wait for system clock switch to PLL */
    }

    /* -------------------------------------------------------------------------
     * 3. GPIO Clocks: GPIOA (USART2) and GPIOC (I2C3)
     * ------------------------------------------------------------------------- */
    RCC->AHB2ENR |= (RCC_AHB2ENR_GPIOAEN | RCC_AHB2ENR_GPIOCEN);

    /* -------------------------------------------------------------------------
     * 4. USART2 Initialization (PA2 = TX, PA3 = RX, 1 MBaud, 170 MHz PCLK1)
     * ------------------------------------------------------------------------- */
    /* PA2: Alternate Function 7 (AF7), High-Speed */
    GPIOA->MODER &= ~GPIO_MODER_MODE2;
    GPIOA->MODER |= (2UL << GPIO_MODER_MODE2_Pos);
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL2;
    GPIOA->AFR[0] |= (7UL << GPIO_AFRL_AFSEL2_Pos);
    GPIOA->OSPEEDR |= (3UL << GPIO_OSPEEDR_OSPEED2_Pos);

    /* PA3: Alternate Function 7 (AF7), Input Pull-Up */
    GPIOA->MODER &= ~GPIO_MODER_MODE3;
    GPIOA->MODER |= (2UL << GPIO_MODER_MODE3_Pos);
    GPIOA->AFR[0] &= ~GPIO_AFRL_AFSEL3;
    GPIOA->AFR[0] |= (7UL << GPIO_AFRL_AFSEL3_Pos);
    GPIOA->PUPDR &= ~GPIO_PUPDR_PUPD3;
    GPIOA->PUPDR |= (1UL << GPIO_PUPDR_PUPD3_Pos);

    /* Enable USART2 Peripheral Clock (defaults to PCLK1 = 170 MHz) */
    RCC->APB1ENR1 |= RCC_APB1ENR1_USART2EN;

    /* Baud rate: 170 MHz / 1,000,000 = 170 (0xAA) */
    USART2->BRR = 170UL;

    /* 8 data bits, 1 stop bit, oversampling by 16 (OVER8 = 0 default) */
    USART2->CR1 = USART_CR1_TE | USART_CR1_RE | USART_CR1_UE;

    /* -------------------------------------------------------------------------
     * 5. I2C3 Initialization (PC8 = SCL, PC9 = SDA, Standard Mode 100 kHz)
     * ------------------------------------------------------------------------- */
    /* PC8 & PC9: Alternate Function 8 (AF8), Open-Drain */
    GPIOC->MODER &= ~(GPIO_MODER_MODE8 | GPIO_MODER_MODE9);
    GPIOC->MODER |= (2UL << GPIO_MODER_MODE8_Pos) | (2UL << GPIO_MODER_MODE9_Pos);

    GPIOC->OTYPER |= (GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9);

    GPIOC->AFR[1] &= ~(GPIO_AFRH_AFSEL8 | GPIO_AFRH_AFSEL9);
    GPIOC->AFR[1] |= (8UL << GPIO_AFRH_AFSEL8_Pos) | (8UL << GPIO_AFRH_AFSEL9_Pos);

    /* Enable I2C3 Peripheral Clock (defaults to PCLK1 = 170 MHz) */
    RCC->APB1ENR1 |= RCC_APB1ENR1_I2C3EN;

    /* Disable I2C3 before programming TIMINGR */
    I2C3->CR1 &= ~I2C_CR1_PE;

    /* Timing register: PRESC = 16 (0xF), SCLL = 49 (0x31), SCLH = 47 (0x2F),
     * SDADEL = 2 (0x2), SCLDEL = 4 (0x4)
     */
    I2C3->TIMINGR = (15UL << I2C_TIMINGR_PRESC_Pos)
                  | (4UL  << I2C_TIMINGR_SCLDEL_Pos)
                  | (2UL  << I2C_TIMINGR_SDADEL_Pos)
                  | (47UL << I2C_TIMINGR_SCLH_Pos)
                  | (49UL << I2C_TIMINGR_SCLL_Pos);

    /* Enable I2C3 */
    I2C3->CR1 |= I2C_CR1_PE;

    /* Loop forever waiting for tasks / low-power transitions */
    while (1) {
